package org.apache.commons.math3.optimization.univariate;

import org.apache.commons.lang3.builder.EqualsBuilder;
import org.junit.*;
import static org.junit.Assert.*;

public class UnivariatePointValuePairSymflowerTest {
	@Test
	public void UnivariatePointValuePair1() {
		double point = 0.0D;
		double value = 0.0D;
		UnivariatePointValuePair expected = new UnivariatePointValuePair(0.0D, 0.0D);
		UnivariatePointValuePair actual = new UnivariatePointValuePair(point, value);

		assertTrue(EqualsBuilder.reflectionEquals(expected, actual, false, null, true));
	}

	@Test
	public void getPoint2() {
		UnivariatePointValuePair u = new UnivariatePointValuePair(0., 0.);
		double expected = 0.;
		double actual = u.getPoint();

		assertEquals(expected, actual, 0.0000001D);
	}

	@Test
	public void getValue3() {
		UnivariatePointValuePair u = new UnivariatePointValuePair(0., 0.);
		double expected = 0.;
		double actual = u.getValue();

		assertEquals(expected, actual, 0.0000001D);
	}
}
